css:
.control {
  display: flex;
  gap: 0;
  max-width: 320px;
  padding: 4px;
  border: 1px solid #a1a1aa;
  border-radius: 8px;
  background: #f4f4f5;
}

.seg {
  flex: 1; /* share the row equally */
  padding: 8px 12px;
  border: 0;
  border-radius: 6px;
  background: transparent;
}

.active {
  background: #18181b;
  color: #fafafa;
}
